import java.util.Scanner;

public class Main10 {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        int val = input.nextInt();
        String data = input.next();
        String tempData = data;
        String bracketsStr = "_";
        int startIndex = -1;
        int dataLength = tempData.length();

        for (int i = 0; i < dataLength; i++) {
            char ch = tempData.charAt(i);
            if (ch == '(') {
                startIndex = i;
            } else if (ch == ')') {
                bracketsStr += tempData.substring(startIndex + 1, i) + "_";
                tempData = tempData.substring(0, startIndex) + "_" + tempData.substring(i + 1);
                dataLength = tempData.length();
                i = startIndex - 1;
                startIndex = -1;
            }
        }
        String[] bracketParts = bracketsStr.split("_");
        int countBrackets = 0;
        for (String part : bracketParts) {
            if (!part.equals("")) {
                countBrackets++;
            }
        }
        String[] segmentsArray = tempData.split("_");
        int maxSegment = 0;
        for (String segment : segmentsArray) {
            if (segment.length() > maxSegment) {
                maxSegment = segment.length();
            }
        }
        System.out.println(maxSegment + " " + countBrackets);
    }
}
